PRAGMA foreign_keys = ON;

BEGIN TRANSACTION;

INSERT INTO core_publication
  (publication_type, pmid, authors, title, journal, publication_date, url,
   contains_promoter_data, contains_expression_data, submission_notes, curation_complete,
   reported_TF, reported_species)
SELECT
  'ARTICLE',
  '42331927',
  'Basta S, Montagnani E, Gori M',
  'A proof of concept approach to quantify body schema using local Shannon entropy.',
  'Scientific reports',
  '2026 Jun 22',
  'https://doi.org/10.1038/s41598-026-59332-x',
  0,
  1,
  'Test for DB evidence_type introduction',
  1,
  'LgnR',
  'Pseudomonas stutzeri RCH2'
WHERE NOT EXISTS (
  SELECT 1 FROM core_publication WHERE pmid='42331927'
);

UPDATE core_publication
SET
  authors = CASE WHEN authors IS NULL OR authors='' THEN 'Basta S, Montagnani E, Gori M' ELSE authors END,
  title = CASE WHEN title IS NULL OR title='' THEN 'A proof of concept approach to quantify body schema using local Shannon entropy.' ELSE title END,
  journal = CASE WHEN journal IS NULL OR journal='' THEN 'Scientific reports' ELSE journal END,
  publication_date = CASE WHEN publication_date IS NULL OR publication_date='' THEN '2026 Jun 22' ELSE publication_date END,
  url = CASE WHEN url IS NULL OR url='' THEN 'https://doi.org/10.1038/s41598-026-59332-x' ELSE url END,
  reported_TF = CASE WHEN reported_TF IS NULL OR reported_TF='' THEN 'LgnR' ELSE reported_TF END,
  reported_species = CASE WHEN reported_species IS NULL OR reported_species='' THEN 'Pseudomonas stutzeri RCH2' ELSE reported_species END,
  contains_promoter_data = 0,
  contains_expression_data = 1,
  curation_complete = 1,
  submission_notes = CASE
    WHEN submission_notes IS NULL OR submission_notes='' THEN 'Test for DB evidence_type introduction'
    ELSE submission_notes
  END
WHERE pmid='42331927';

INSERT INTO core_tf (name, family_id, description)
SELECT 'LgnR', 31, 'LgnR is an IclR family transcriptional regulator [PMID::24336464].'
WHERE NOT EXISTS (
  SELECT 1 FROM core_tf WHERE lower(name)=lower('LgnR')
);

UPDATE core_tf
SET
  family_id = COALESCE(family_id, 31),
  description = CASE WHEN description IS NULL THEN 'LgnR is an IclR family transcriptional regulator [PMID::24336464].' ELSE description END
WHERE lower(name)=lower('LgnR');

INSERT INTO core_tfinstance (refseq_accession, uniprot_accession, description, TF_id, notes)
SELECT
  'WP_000107102',
  'Q0WJZ2',
  'zinc uptake transcriptional repressor [Yersinia pestis biovar Microtus str. 91001].',
  (SELECT TF_id FROM core_tf WHERE lower(name)=lower('LgnR') LIMIT 1),
  ''
WHERE NOT EXISTS (
  SELECT 1 FROM core_tfinstance WHERE uniprot_accession='Q0WJZ2'
);

UPDATE core_tfinstance
SET
  TF_id = COALESCE(TF_id, (SELECT TF_id FROM core_tf WHERE lower(name)=lower('LgnR') LIMIT 1)),
  refseq_accession = COALESCE(NULLIF(refseq_accession,''), 'WP_000107102'),
  description = COALESCE(NULLIF(description,''), 'zinc uptake transcriptional repressor [Yersinia pestis biovar Microtus str. 91001].'),
  notes = COALESCE(notes, '')
WHERE uniprot_accession='Q0WJZ2';

INSERT INTO core_curation
  (TF_species, site_species, experimental_process, forms_complex,
   complex_notes, notes, last_modified, curator_id, publication_id, created, validated_by_id)
VALUES
  ('Pseudomonas stutzeri RCH2', 'Pseudomonas stutzeri RCH2', NULL,
   0, NULL, 'Test for DB evidence_type introduction',
   datetime('now'), (SELECT curator_id FROM core_curator ORDER BY curator_id LIMIT 1), (SELECT publication_id FROM core_publication WHERE pmid='42331927' LIMIT 1), datetime('now'), NULL);

INSERT INTO core_curation_TF_instances (curation_id, tfinstance_id)
SELECT (SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='42331927' LIMIT 1) ORDER BY curation_id DESC LIMIT 1), (SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q0WJZ2' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM core_curation_TF_instances
  WHERE curation_id=(SELECT curation_id FROM core_curation WHERE publication_id=(SELECT publication_id FROM core_publication WHERE pmid='42331927' LIMIT 1) ORDER BY curation_id DESC LIMIT 1) AND tfinstance_id=(SELECT TF_instance_id FROM core_tfinstance WHERE uniprot_accession='Q0WJZ2' LIMIT 1)
);

